  "a4z0qg": "Son Oyunlar / Endgame",
  "rxiob": "Her hareketin öncesinde, “Düşmanım ne tehdit etti? Bu hareketin ardından, benim parçalarımdan hangisi savunmasızdır?”",
  "1iwpe2z": "Her döner, önce kontrollere, yakalamaya ve tehditlere bakın: kazanan darbe genellikle orada.",
  "qrpsfi": "Karşılaştırma desenleri öğrenin (balk sıralaması, Arapça, Boden, kaymazlık...) böylece bir oyun sırasında onları görebilirsiniz.",
  "xhwanc": "Merkezin üstüne, önce şövalyeler ve piskoposlar geliştirmek, kalenin erken, ve bir parça gerek olmadan iki kez hareket etmeyin.",
  "1ulggiy": "10 Hareket etmeye başlamadan önce kalın ve kralınızı kaplayan kalınları tutun; düşman kralı hala ortasında olduğunda, merkezini açın ve saldırın.",
  "1t15fl6": "Taktik yoksa: en kötü parçasını bul, daha iyi bir çeyrekte getirin ve açılan dosyaları köşelerinizle alın.",
  "1fs9wy0": "Malzemeyi ilerlerken: parça değiştirin, kralınızı getirin ve geçmiş bir kalem bastırın. Acele etmeyin: Her hareketi kontrol edin, böylece çarpışmazsınız.",
  "7xpp3j": "Cevap 1.e4 ile 1...e5 (Açık Oyun)",
