  "1pt5m6n": "Sık sık sorun yaşıyorsunuz:",
  "16dg98h": "Bu soruyu anlamadım ve Bilgi Kütüphanesinde uygun bir makale bulamadım. Aşağıdaki öneriyi veya daha kısa bir anahtar kelimeyi deneyin (örneğin: pin, geçmiş pawn, Lucena).",
  "hwnfby": "Sunucu çok yoğun, lütfen birkaç dakika içinde tekrar deneyin.",
  "1b2hmqy": "Asistanın sunucusuna bağlanamaz.",
  "1d5b5ty": "Sunucu çok meşgul, geri çekiliyor...",
  "rq1kpk": "Bir cevap bulamadım lütfen başka bir soru sormaya çalışın.",
  "15d632n": "Yardımcıların servisinde bir hata vardı.",
  "gqs80q": "Stockfish 19 Oyunu analiz ediyor",
  "uemrrc": "Bilgisayar karşısında veya çevrimiçi birkaç oyun oynayın: Stockfish 19 dereceleri her hareketi, ve asistan zayıflıklarınızı bulur ve sizin için bir plan oluşturur.",
  "1f3rsx8": "Başlangıç pozisyonundan birkaç oyun oynayın, ortak açılımlarınızı ve puanlarınızı görmek için.",
  "11u3lth": "Tarihte henüz oyun yok. Bilgisayar veya çevrimiçi karşı bir oyun oynayın ve asistanı incelemek için burada görünür.",
  "o4mziy": "En son oyunlarımı inceleyin",
