  "1tnlvlj": "Hangi açılımları kendi seviyemde oynamalıyım?",
  "tuu2bl": "Merhaba, bugün nasıl yardımcı olabilirim?",
  "jcj48p": "Oyunlarınızı okuyorum, her satırı Stockfish 19 ile kontrol ediyorum ve cevap vermeden önce Bilgi Kütüphanesinde şeyleri inceliyorum.",
  "l620kc": "Zayıflıkları bulmak ve bir çalışma planı önermek için Stockfish 19 tarafından analiz edilen oyunları okudum. Bilgi Kütüphanesi'ni aramak için bir kavram yazın (pin, Lucena, Sicilian...)",
