  "1whuabj": "{0}. Daha iyi ise {1} oldu.",
  "17q4hb2": "Her iki taraf da {0} hareketinde krallar ticaret: daha az parça ile, kral daha erken mücadele katılabilir.",
  "t5n6eb": "Sen kraliçenizi teslim etmek için hareket {0}'e kurban ettin. Güzel bir bitim!",
  "yhdlku": "Kardeşiniz Kraliçe'yi Hareketle Öldürdü {0} Kardeşinizi teslim etmek için: Kralınız engellenirken, her zaman rakibinizin fedakarlık kontrolünü kontrol edin.",
