  "11dgwg2": "(yürüyüş {0}) ve kraliçe hemen geri çekildi, yaklaşık {1} madde puan kaybetti.",
  "cshz0d": "(yürüyüş {0}) ile {1} kötü bir değişim oldu: yakalanma parça hemen geri alınır, yaklaşık {2} madde puan kaybetti.",
  "7no57s": "Bu web sitesi, bu web tarayıcısında açılır",
