  "1sn6cu0": "{0} hareket etmek için. {1}",
  "11gvip4": "{0} kez bir parça kazanmak için bırakın {1} analiz edilen oyunlarda",
  "ubru2n": "{0} daha iyi bir yakalama veya kontrol eksik zamanlar",
  "1k7uin4": "{0} zaman eksik (veya kaybolan) bir kontrol ortağı",
  "1f1euib": "{0} 10 hareketten sonra oyunlar daha kötü, {1} Oyunlar ilk 5 harekette kraliçe hareket",
  "1gniq49": "{0} 12 hareketten sonra oynanmamış oyunlar, {1} Oyun kontrolü",
  "tve09w": "{0} büyük hatalar ve {1} yanlışlıklar",
  "1nlqtu8": "{0} maç kazanılmadı, ≥ 3 puan önde, {1} büyük hatalar son maçta",
  "1m2pm1t": "Özel Stockfish (~{0})",
  "u2p5qr": "{0}: çalışma birimi “{1}”",
  "26fwnn": "Bulmaca Çözme: {0}",
  "1q9h1k3": "Öğrenme Sayısı: {0}",
  "1k8ms8c": "Kütüphane : {0}",
