  "wt9bn": "\"Bir Köprü Yapmak\" - Kral'ı kontrollerden korumak için kayayı kullanın",
  "1xfmuyn": "Ticaret Çatıları",
  "de2frr": "Lucena pozisyonu: Beyaz kral, yün önünde d8'de yer alır. “Bir köprü inşa etmek için çatıyı dördüncü sırada getirin” sonra tanıtın! Bilgisayar siyah oynuyor.",
  "ok3r28": "Kralın kesilmesi",
  "60x3bw": "Neden bir dosya veya sıralama boyunca düşman kralı \"kırmak\" için kayayı kullanın?",
  "1ui0cjd": "Düşman Kralı, çarpışmayı durdurmak için zamanında geri dönemez",
  "ww32hs": "Ticaret Çatıları",
  "x3268c": "Kendi kralı güvende tutmak için",
  "19y4dfu": "Kötü renkli piskopos",
  "1lyiebm": "Kral, piskopos ve h-pawn, ama piskopos h8 promosyon çatı kontrol etmez ve siyah kral köşede. Sonuç nedir ?",
  "1y0ib49": "Rook Endgame İncelemesi",
